-- Fictional rows and deliberately simplified helper boundaries; not full-schema/source admission proof.
create schema if not exists icash_work_private;create schema if not exists icash_research_private;
create function public.fid(n int) returns uuid language sql immutable as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create table public.icash_screening_jobs(id uuid primary key,account_id uuid,completed_at timestamptz,snapshot jsonb);create index on public.icash_screening_jobs(account_id);
create table public.icash_automation_tickets(id uuid primary key,account_id uuid,screening_id uuid unique,kind text,state text,outcome text,owner_preview_deferrals int,owner_preview_retry_after timestamptz,owner_preview_retry_until timestamptz,owner_preview_screening_hash text);
create table public.icash_operation_spend(operation_key text primary key,account_id uuid,state text);
create table icash_research_private.owner_export_preflights(id uuid primary key,account_id uuid,items jsonb,state text,checked_at timestamptz,created_at timestamptz,next_check_at timestamptz,deleted_at timestamptz,cleanup_attempts int,known boolean default true,ready_current boolean default true,two_step boolean default true);
create index owner_preflight_recent_cohorts on icash_research_private.owner_export_preflights(account_id,created_at desc) where state in ('creating','waiting','checking','ready');
create table public.fixture_settings(capacity3 boolean,capacity2 boolean,retry_current boolean);insert into public.fixture_settings values(true,true,true);
create function public.icash_dealmachine_capacity_available(int,uuid) returns boolean language sql stable as $$select capacity3 from public.fixture_settings$$;create function public.icash_dealmachine_capacity_available(int) returns boolean language sql stable as $$select capacity2 from public.fixture_settings$$;
create function icash_research_private.owner_preflight_ready_current(uuid) returns boolean language sql stable as $$select ready_current from icash_research_private.owner_export_preflights where id=$1$$;create function icash_research_private.owner_preflight_list_known(uuid) returns boolean language sql stable as $$select known from icash_research_private.owner_export_preflights where id=$1$$;create function icash_work_private.owner_preflight_two_step_current(uuid) returns boolean language sql stable as $$select two_step from icash_research_private.owner_export_preflights where id=$1$$;
create function public.icash_owner_enrichment_screening_hash(public.icash_screening_jobs) returns text language sql stable as $$select md5(($1).snapshot::text)$$;create function public.icash_owner_enrichment_retry_current(uuid,uuid) returns boolean language sql stable as $$select retry_current from public.fixture_settings$$;create function icash_research_private.owner_preflight_cohort(uuid,uuid) returns jsonb language sql stable as $$select jsonb_build_array(jsonb_build_object('screeningId',$2::text))$$;
insert into public.icash_screening_jobs select fid(n),fid(100000),now()-interval '1 hour',jsonb_build_object('propertyId',n::text,'fetchedAt',now()-interval '1 hour') from generate_series(1,120)n;
insert into public.icash_automation_tickets select id,account_id,id,'contacts','held','owner_preview_rate_limited',1,now()-interval '1 minute',now()+interval '1 hour',md5(snapshot::text) from public.icash_screening_jobs;
insert into icash_research_private.owner_export_preflights(id,account_id,items,state,checked_at,created_at,next_check_at,cleanup_attempts) select id,account_id,jsonb_build_array(jsonb_build_object('screeningId',id::text)),'ready',case when id=fid(1) then now()-interval '1 minute' else now()-interval '1 day' end,now()-interval '1 day',null,0 from public.icash_screening_jobs;
insert into icash_research_private.owner_export_preflights select fid(10000+n),fid(100001),jsonb_build_array(jsonb_build_object('screeningId',fid(n)::text)),'ready',now()-interval '1 minute',now()-interval '1 minute',now()-interval '1 minute',null,0,true,true,true from generate_series(1,30)n;
analyze;
